/** A disjunction over a conjunction retains shared literals, whole Sources and independent refutation routes. */
final class ContextAuthorityAlternativeHead {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static final class Expected {
        final Set<Source> locals=new HashSet<>(),donors=new HashSet<>(),bridges=new HashSet<>();
        final SemanticTermSnapshot x,head,other;final Source premise;Source dm,dt,de;final boolean negative;final int mode;
        Expected(ContextProductionCandidate.Staged a,boolean negative,int mode){
            this.negative=negative;this.mode=mode;for(Entry e:a.staged.primary)locals.add(e.source);Entry base=a.staged.primary.stream().filter(e->!e.source.equals(a.candidate)).findFirst().get();premise=base.source;x=base.clauses.get(0).literals.get(0).arguments.get(0).value;SemanticTermSnapshot h=null,o=null;
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:a.foreign)for(Entry e:cut.primary){if(e.clauses.size()==2){Set<Set<String>> heads=new HashSet<>();for(Clause c:e.clauses){Atom out=c.literals.stream().filter(l->l.predicate.equals("out")).findFirst().get();Set<Integer> slots=new HashSet<>();for(Slot slot:out.arguments){require(slot.variable>=0,"three universal Bridge input slots");slots.add(slot.variable);}require(slots.size()==3&&c.variables.size()==3&&c.literals.size()==3&&out.positive==negative,"whole Bridge antecedent independent inputs/sign");Set<String> predicates=new HashSet<>();for(Atom atom:c.literals)if(!atom.predicate.equals("out")){predicates.add(atom.predicate);require(atom.positive!=negative&&atom.arguments.size()==1,"exact mixed head sign/arity");if(atom.predicate.equals("mid")){require(atom.arguments.get(0).variable<0,"unconditional head is ground literal");if(h==null)h=atom.arguments.get(0).value;else require(h.semanticallyEquals(atom.arguments.get(0).value),"shared mid literal is identical across both whole-Source clauses");}else require(atom.predicate.equals("tail")&&atom.arguments.get(0).variable==out.arguments.get(0).variable||atom.predicate.equals("extra")&&atom.arguments.get(0).variable==out.arguments.get(2).variable,"disjunctive tail/extra exact input mapping");}require(heads.add(predicates),"no duplicate Bridge clause");}require(heads.equals(new HashSet<>(Arrays.asList(new HashSet<>(Arrays.asList("mid","tail")),new HashSet<>(Arrays.asList("mid","extra"))))),"one whole Source owns two disjunctive clauses sharing mid");bridges.add(e.source);}
                else{require(e.clauses.size()==1&&e.clauses.get(0).literals.size()==1,"private donor or Deny is one unit clause");Clause c=e.clauses.get(0);Atom atom=c.literals.get(0);if(atom.predicate.equals("q")){require(c.variables.size()==3&&atom.positive!=negative,"independent universal donor");donors.add(e.source);}else{require(atom.positive==negative&&c.variables.isEmpty()&&atom.arguments.size()==1,"opposite ground Deny");if(atom.predicate.equals("mid"))dm=e.source;else if(atom.predicate.equals("tail"))dt=e.source;else{require(atom.predicate.equals("extra"),"known Deny endpoint");de=e.source;}if(atom.predicate.equals("extra")||mode==6&&atom.predicate.equals("tail")||(mode==5||mode==10)&&atom.predicate.equals("mid"))o=atom.arguments.get(0).value;}}
            }
            head=h;other=o;require(locals.size()==2&&locals.contains(a.candidate)&&donors.size()==3&&bridges.size()==2&&h!=null&&!h.semanticallyEquals(x),"whole X2, three donors, two whole two-clause Bridges and head literal");require(donors.stream().map(v->v.context).distinct().count()==3&&bridges.stream().map(v->v.context).distinct().count()==2,"independent private origins");require((dm!=null)==(mode==1||mode==5||mode>=7)&&(dt!=null)==(mode==2||mode==4||mode==5||mode==6||mode==7||mode==9||mode==10)&&(de!=null)==(mode==3||mode==4||mode==6||mode==8||mode==9||mode==10),"exact case-specific Deny topology");if(o!=null)require(!o.semanticallyEquals(x)&&!o.semanticallyEquals(h),"third distinct private value");
        }
        Set<Source> set(Source... extra){Set<Source> v=new HashSet<>(locals);v.addAll(Arrays.asList(extra));return v;}
        Set<Set<Source>> alternatives(Source extra){Set<Set<Source>> result=new HashSet<>();for(Source q:donors)for(Source b:bridges){Set<Source> v=set(q,b);if(extra!=null)v.add(extra);result.add(v);}return result;}
    }
    static boolean ground(Atom a,SemanticTermSnapshot value){return a.arguments.size()==1&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(value);}
    static boolean counter(Clause c,Expected e,boolean tailRoute){int variables=tailRoute?2:1;if(c.variables.size()!=variables||c.literals.size()!=1)return false;Atom a=c.literals.get(0);if(a.arguments.size()!=3||a.arguments.get(0).variable>=0||!a.arguments.get(0).value.semanticallyEquals(e.x)||a.arguments.get(1).variable<0)return false;return tailRoute?a.arguments.get(2).variable>=0&&a.arguments.get(1).variable!=a.arguments.get(2).variable:a.arguments.get(2).variable<0&&a.arguments.get(2).value.semanticallyEquals(e.other);}
    static void disjunction(ContextUniversalUnitRounds.Frontier f,Expected e,int count){Map<String,Set<Set<Source>>> actual=new HashMap<>();actual.put("tail",new HashSet<>());actual.put("extra",new HashSet<>());for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==2){Map<String,Atom> atoms=new HashMap<>();for(Atom a:row.clause.literals)atoms.put(a.predicate,a);if(!atoms.containsKey("mid")||!atoms.containsKey("tail")&&!atoms.containsKey("extra"))continue;String branch=atoms.containsKey("tail")?"tail":"extra";Atom a=atoms.get(branch);require(atoms.get("mid").positive!=e.negative&&a.positive!=e.negative&&ground(atoms.get("mid"),e.head)&&row.support.depth==3&&actual.get(branch).add(row.support.sources),"whole shared-mid disjunction, exact depth and unique Source alternative");if(branch.equals("tail"))require(row.clause.variables.isEmpty()&&ground(a,e.x),"mid/tail disjunction retains exact fixed producer value");else require(row.clause.variables.size()==1&&a.arguments.size()==1&&a.arguments.get(0).variable>=0,"mid/extra disjunction retains universal extra slot");}for(Set<Set<Source>> routes:actual.values())require(routes.size()==count&&(count==0||routes.equals(e.alternatives(null))),"all six exact alternatives for each shared-literal disjunction");}
    static void extra(ContextUniversalUnitRounds.Frontier f,Expected e,Set<Set<Source>> expected){Set<Set<Source>> actual=new HashSet<>();int count=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("extra")){++count;Atom a=row.clause.literals.get(0);require(a.positive!=e.negative&&a.arguments.size()==1&&a.arguments.get(0).variable>=0&&row.clause.variables.size()==1&&row.support.depth==4&&actual.add(row.support.sources),"selected extra is universal, exact depth4 and unique support");}require(count==expected.size()&&actual.equals(expected),"all independently enumerated selected universal extra alternatives");}
    static void units(ContextUniversalUnitRounds.Frontier f,Expected e,String predicate,int depth,SemanticTermSnapshot value,Set<Set<Source>> expected){Set<Set<Source>> actual=new HashSet<>();int n=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1){Atom atom=row.clause.literals.get(0);if(!atom.predicate.equals(predicate))continue;++n;require(atom.positive!=e.negative||predicate.equals("p1"),"exact selected head sign");if(predicate.equals("p1"))require(atom.positive,"positive displaced premise");require(row.clause.variables.isEmpty()&&ground(atom,value)&&row.support.depth==depth&&actual.add(row.support.sources),"exact selected ground unit, depth and unique support");}require(n==expected.size()&&actual.equals(expected),"all independently enumerated alternatives for "+predicate);}
    static void out(ContextUniversalUnitRounds.Frontier f,Expected e){Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();for(Source q:e.donors)expected.add(e.set(q));for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out")){Atom a=row.clause.literals.get(0);require(a.positive!=e.negative&&a.arguments.size()==3&&row.clause.variables.size()==2&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(e.x)&&a.arguments.get(1).variable>=0&&a.arguments.get(2).variable>=0&&a.arguments.get(1).variable!=a.arguments.get(2).variable&&row.support.depth==2&&actual.add(row.support.sources),"three independently supported out schemas preserve both free coordinates");}require(actual.equals(expected),"exact out support alternatives");}
    static void consistent(Result r,Expected e,int mode){require(r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers==(mode==0?3:4),"case-specific stable alternative-family certificate");ContextUniversalFamilyModel.Certificate cert=r.certificate;require(cert.cuts.size()==6+(e.dm==null?0:1)+(e.dt==null?0:1)+(e.de==null?0:1)&&cert.cuts.size()==cert.input.cuts.size(),"all exact pinned family cuts");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:cert.cuts){require(cut.receipt.verified&&cut.receipt.input==cert.input&&cut.model.ledger==cut.receipt.closureStep.input,"exact model/closure binding");receipts.add(cut.receipt);models.add(cut.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-values recertification");out(cert.input,e);disjunction(cert.input,e,6);Set<Set<Source>> empty=Collections.emptySet(),mid=new HashSet<>();if(mode==2||mode==4||mode==5||mode==10)mid.addAll(e.alternatives(e.dt));if(mode==3||mode==4||mode==6||mode==10)mid.addAll(e.alternatives(e.de));units(cert.input,e,"mid",4,e.head,mid);units(cert.input,e,"tail",4,e.x,mode==1?e.alternatives(e.dm):empty);extra(cert.input,e,mode==1?e.alternatives(e.dm):empty);units(cert.input,e,"p1",4,e.other,empty);int rows=mode==0?39:mode==6?63:mode==1||mode==4||mode==10?71:55;int count=mode==0?3:mode==1||mode==4||mode==10?15:9;require(cert.input.products.size()==rows&&cert.input.products.stream().filter(row->row.clause.literals.size()==1).count()==count,"exact full frontier/unit counts, no false p1 or unconditional branch import");}
    static void collision(Result r,Expected e,boolean exactLocal){require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==4&&r.collision.oppositions.size()==(e.mode==9?36:18),"complete independent refutation routes at fourth barrier");Map<Set<Source>,Set<String>> actual=new HashMap<>();Set<Set<Source>> expected=new HashSet<>();for(Source q:e.donors)for(Source b:e.bridges){if(e.dt!=null)expected.add(new HashSet<>(Arrays.asList(q,b,e.dm,e.dt)));if(e.de!=null)expected.add(new HashSet<>(Arrays.asList(q,b,e.dm,e.de)));}for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.depth==5&&p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==4&&p.rightSupport.sources.size()==5&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole depth5 refutation from original unit versus depth4 transport");Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source v:p.support.sources)(v.localX?local:foreign).add(v);require(local.size()==2&&foreign.size()==4&&p.support.sources.size()==6&&foreign.contains(e.dm)&&expected.contains(foreign),"proof uses exact Mid-Deny plus one branch Deny, never all-three superset");if(exactLocal)require(local.equals(e.locals),"fresh exact local Sources");boolean tailRoute=foreign.contains(e.dt);Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive,"opposite same endpoint");if(l.predicate.equals("q"))require(l.positive!=e.negative&&p.left.variables.size()==3&&p.leftSupport.sources.stream().anyMatch(e.donors::contains)&&counter(p.right,e,tailRoute),"route-specific counter-q preserves exactly its independent free coordinates");else if(l.predicate.equals("extra"))require(!tailRoute&&l.positive==e.negative&&ground(l,e.other)&&p.leftSupport.sources.contains(e.de)&&p.right.variables.size()==1&&rr.arguments.get(0).variable>=0,"private extra instance opposes universally selected extra");else require(l.positive==e.negative&&p.right.variables.isEmpty()&&ground(l,l.predicate.equals("mid")?e.head:e.x)&&ground(rr,l.predicate.equals("mid")?e.head:e.x)&&p.leftSupport.sources.contains(l.predicate.equals("mid")?e.dm:e.dt),"exact original mid/tail refutation endpoint");require(actual.computeIfAbsent(foreign,k->new HashSet<>()).add(l.predicate),"no duplicate endpoint hides another route");}require(actual.keySet().equals(expected),"all independently enumerated donor/Bridge/Deny-pair routes survive");for(Map.Entry<Set<Source>,Set<String>> route:actual.entrySet())require(route.getValue().equals(new HashSet<>(route.getKey().contains(e.dt)?Arrays.asList("q","mid","tail"):Arrays.asList("q","mid","extra"))),"every route has all three exact endpoints");}
    static void barriers(ContextProductionCandidate.Staged a,Expected e){ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"immutable first barrier");out(first.frontier,e);disjunction(first.frontier,e,0);int saved=first.frontier.products.size();ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"immutable second barrier");out(second.frontier,e);disjunction(second.frontier,e,6);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==3,"second barrier exports two whole disjunctions but no unconditioned head units");}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,65536,1000000,WORK,500000,WORK);}
    static void one(boolean negative,boolean reverse,int mode,boolean nativePath)throws Exception{
        Path dir=Files.createTempDirectory("alternative-head-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";List<String> names=new ArrayList<>();
        for(String name:new String[]{"A1","A2","A3"}){ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"q(x,y,z);");names.add(name);}for(String name:new String[]{"Bridge1","Bridge2"}){ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"out(x,y,z)->"+sign+"mid(2)||("+sign+"tail(x)&&"+sign+"extra(z));");names.add(name);}
        if(mode==1||mode==5||mode>=7){ContextAuthorityChain.create(dir,"DenyMid","!"+(negative?"":"~")+(mode==5||mode==10?"mid(9);":"mid(2);"));names.add("DenyMid");}if(mode==2||mode==4||mode==5||mode==6||mode==7||mode==9||mode==10){ContextAuthorityChain.create(dir,"DenyTail","!"+(negative?"":"~")+(mode==6?"tail(9);":"tail(1);"));names.add("DenyTail");}if(mode==3||mode==4||mode==6||mode==8||mode==9||mode==10){ContextAuthorityChain.create(dir,"DenyExtra","!"+(negative?"":"~")+"extra(9);");names.add("DenyExtra");}if(reverse)Collections.reverse(names);
        String text="!@x @y @z "+sign+"q(x,y,z)&&~p1(x)->"+sign+"out(x,y,z);";boolean conflict=mode>=7&&mode<=9;Set<String> origins;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile("!~p1(1);",null,false),"original premise");for(String name:names)f.db.connectContext(name);f.db.saveConnections(f.root);ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initialOrigins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);require(initialOrigins.size()==1&&pins.size()==names.size(),"only original premise and exact saved topology");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"disjunction mode"+mode+": "+diagnostic.reason);Expected expected=new Expected(diagnostic.artifact,negative,mode);
            Entry candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get();require(candidate.clauses.size()==1&&candidate.clauses.get(0).variables.size()==3&&candidate.clauses.get(0).literals.size()==3,"whole independent three-variable candidate");
            if(conflict)collision(diagnostic.qualification,expected,true);else consistent(diagnostic.qualification,expected,mode);barriers(diagnostic.artifact,expected);
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.collision==null&&stopped.qualification.certificate==null&&stopped.reason.contains("common round limit"),"round cap never exposes a partial verdict");require(f.db.getRevision()==revision&&f.root.getRules().size()==rules&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical state");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"fresh native-child conflict independently audited");collision(failure.getFamilyAudit().verdict,expected,false);}else require(failure==null,"actual native disjunctive family accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer settles mode"+mode+": "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial&&result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"fresh audit and exact physical revision references");Expected fresh=new Expected(result.trial.artifact,negative,mode);if(conflict)collision(result.trial.qualification,fresh,true);else{require(result.audit.oppositions.isEmpty(),"compatible disjunction has no collision attribution");consistent(result.trial.qualification,fresh,mode);}}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);origins=ContextSevenPremiseNativeWriteRunner.origins(after);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"exact saved pin order unchanged");if(conflict)require(settled==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint)&&origins.equals(initialOrigins),"both-Deny refusal preserves exact original theory");else{require(settled>revision&&after.primary.size()==2&&origins.size()==2&&origins.containsAll(initialOrigins),"only one whole candidate published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,after,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==2&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate.clauses.get(0))),"actual published primary is exact requested rule");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate.clauses.get(0))||e.clauses.get(0).literals.size()==1&&e.clauses.get(0).literals.get(0).predicate.equals("p1")&&!e.clauses.get(0).literals.get(0).positive)),"no disjunct, private assertion or displaced p1 imported as primary");}
            System.out.println("ALTERNATIVE mode="+mode+" negative="+negative+" reverse="+reverse+" native="+nativePath+" barriers="+diagnostic.qualification.completedBarriers);
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?1:2)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(origins)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary reopen retains exact source theory and topology");}
    }
    static void run(boolean negative,boolean reverse,boolean proofs,String marker){try{for(int mode=proofs?7:0;mode<(proofs?11:7);mode++)for(boolean nativePath:new boolean[]{false,true})one(negative,reverse,mode,nativePath);System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
}
